function pixelSelect(select){if(!select||select.dataset.pixelReady)return;select.dataset.pixelReady='1';const wrap=document.createElement('div');wrap.className='pixel-select';wrap.dataset.open='false';const button=document.createElement('button');button.type='button';button.className='pixel-select-button';button.setAttribute('aria-label',select.getAttribute('aria-label')||select.labels?.[0]?.textContent?.trim()||'Choose an option');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');const menu=document.createElement('div');menu.className='pixel-select-menu';menu.setAttribute('role','listbox');menu.hidden=true;const refresh=()=>{const options=[...select.options];button.textContent=options[select.selectedIndex]?.textContent||'Choose';for(const [i,opt] of options.entries()){const item=menu.children[i];if(item){item.setAttribute('aria-selected',String(i===select.selectedIndex));item.classList.toggle('selected',i===select.selectedIndex);}}};[...select.options].forEach((opt,i)=>{const item=document.createElement('button');item.type='button';item.className='pixel-select-option';item.setAttribute('role','option');item.textContent=opt.textContent;item.setAttribute('aria-selected',String(i===select.selectedIndex));item.disabled=opt.disabled;item.onclick=()=>{select.selectedIndex=i;select.dispatchEvent(new Event('change',{bubbles:true}));refresh();menu.hidden=true;wrap.dataset.open='false';button.setAttribute('aria-expanded','false');button.focus();};menu.append(item);});const close=()=>{menu.hidden=true;wrap.dataset.open='false';button.setAttribute('aria-expanded','false');};button.onclick=()=>{const open=menu.hidden;menu.hidden=!open;wrap.dataset.open=String(open);button.setAttribute('aria-expanded',String(open));};button.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='Enter'||e.key===' '){e.preventDefault();menu.hidden=false;wrap.dataset.open='true';button.setAttribute('aria-expanded','true');menu.querySelector('[aria-selected="true"]:not(:disabled)')?.focus();}};menu.onkeydown=e=>{const items=[...menu.querySelectorAll('.pixel-select-option:not(:disabled)')],i=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close();button.focus();}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}else if(e.key==='Home'||e.key==='End'){e.preventDefault();items[e.key==='Home'?0:items.length-1]?.focus();}};menu.addEventListener('focusout',()=>setTimeout(()=>{if(!wrap.contains(document.activeElement))close();},0));select.insertAdjacentElement('afterend',wrap);wrap.append(button,menu);select.classList.add('pixel-select-source');select.setAttribute('aria-hidden','true');select.tabIndex=-1;select.addEventListener('change',refresh);refresh();}
