 if($('#quiz-pic'))drawPic(crispCtx($('#quiz-pic')),askPic(pic),1);quizZoom(askPic(pic));fitQuestion();
 const bindForm=()=>{$('#quiz-form').onsubmit=e=>{
  e.preventDefault();if(done)return;
  const input=$('#quiz-answer').value,before=ready(),r=answerPlacement(s,run,q.id,input);if(!r)return;done=true;/* improve20-z-nov1 #2: two misses in a row in one grade end the check kindly */const stopped=stopPlacement(run);
  const lv=earn(r.xp,before);$('#quiz-answer').disabled=true;$('#quiz-check').disabled=true;
  $('#quiz-feedback').innerHTML=`<div class="feedback">${answerMomentHTML({ok:r.ok,xp:r.xp,nth:run.i,answer:q.answer,level:lv,mastered:r.mastered})}${spellNote(input,q)}<p>${esc(q.explanation||'')}</p>${!r.ok?readButtonHTML(`The answer is ${q.answer}. ${q.explanation||''}`):''}${stopped?(run.streak?'<p class="placement-stop" data-placement-stop="streak">Let’s start with the lesson; nothing is lost. What you got right still counts.</p>':'<p class="placement-stop" data-placement-stop>That is enough for this check. Let’s see where you start.</p>'):''}</div>`;
  questionInView();sfx(r.ok?'correct':'wrong');$('#quiz-next').hidden=false;$('#quiz-next').textContent=run.i<run.items.length?'Next question':'See results';$('#quiz-next').focus();
 };wireChoices($('#quiz-form'),q);/* "Type it instead" swaps the tiles for the typing box, as in the quiz; graded the same either way */const ti=$('#quiz-form [data-type-instead]');if(ti)ti.onclick=()=>{$('#quiz-form').outerHTML=typedForm();bindForm();$('#quiz-answer').focus({preventScroll:true});};};bindForm();
