function fieldMissionPanel(fromJournal=false){const m=fieldMission(s),q=m.task;show('field-mission',header('Supplies for the watch',q?`South gate · Task ${m.at+1} of 3`:'Delivery prepared')+`<section class="field-mission">${q?`<div class="field-top"><span class="tag">${esc(q.title)}</span><span class="field-stars">${sittingPipsHTML(3,m.at,[0,1,2].map(i=>i<m.at?true:undefined),`Task ${m.at+1} of 3`)}</span></div>${/* improve20-t-oct31 #19: the reward, shown before the first task (game/field-mission.js fieldGold) */m.rewarded?'':`<p class="field-offer">${levelIcon('gold',24)}<span>Finish all 3 tasks: <strong>+${m.reward} gold</strong> and a health potion, once.</span></p>`}<h3>${questionHTML(q)}</h3>${readButtonHTML(q.prompt)}${q.visual?`<div class="supply-groups${q.visualLayout==='rows'?' supply-rows':''}" aria-label="${esc(q.visual.map(n=>n+' items').join(', '))}">${q.visual.map(n=>`<span>${supplyIcons(q,n)}</span>`).join('')}</div>`:''}<form id="field-form"><label for="field-answer">Your answer</label><input id="field-answer" inputmode="decimal" autocomplete="off"><button class="primary">Check supplies</button></form><p id="field-feedback" role="status" aria-live="polite"></p><details><summary>Show a hint</summary><p>${esc(q.hint)}</p></details><p class="subtle">No timer. Mistakes are fine.</p>`:/* oct25-followups2 (first-hour playtest: the delivery screen was nearly empty): a small reward moment in the result screen's style -- what you did (the three tasks and their working), what you got (the same FIELD_REWARD, paid once), and the next goal */deliveryHTML({m,tasks:FIELD_TASKS[m.stage],goal:nextStep(s).text,icon:n=>levelIcon(n),overflow:BAG.overflow})}<div class="modal-actions">${fromJournal?'<button id="field-journal">Back to journal</button>':''}<button id="field-town">Return to adventure</button></div></section>`);$('#field-journal')?.addEventListener('click',()=>{journal();$('#journal-adventure').click();});mountDelivery($('#modal-content'));$('#field-town').onclick=forceClose;let checked=false;$('#field-form')?.addEventListener('submit',e=>{e.preventDefault();if(checked)return;const r=answerFieldMission(s,$('#field-answer').value);const fb=$('#field-feedback');if(!r.ok){fb.textContent=`Not quite. ${q.hint}`;sfx('wrong');$('#field-answer').focus();return;}checked=true;persist();updateHUD();sfx('correct');$('#field-answer').disabled=true;$('#field-form button').disabled=true;$('#field-form').hidden=true;$('.field-mission details').hidden=true;/* polish2-oct29: the quiz's answer moment, the task's star lighting with a coin chime as it lands (no timer; reduced motion: no burst) */fb.innerHTML=fieldRightHTML({moment:answerMomentHTML({ok:true,nth:m.at}),explanation:q.explanation,gold:r.gold,goldIcon:levelIcon('gold',24)})+(r.potion?`<p class="field-gold">${icon('potion')}<strong>${r.potion.added?'+1 health potion for the road!':`Potion bag full (${BAG.cap} of ${BAG.cap}): +${r.potion.gold} gold instead`}</strong></p>`:'');quizMoment(document,m.at,true,{pips:FIELD_PIPS,onLand:()=>sfx('coin')});const b=document.createElement('button');b.id='field-next';b.className='primary';b.textContent=r.done?'See the delivery':'Next task';b.onclick=()=>fieldMissionPanel(fromJournal);$('.field-mission .modal-actions').prepend(b);b.focus();});}
