function pause(returning=false){/* oct24-exploit-b: no menu, map, journal or settings over a cinematic (a blur mid-epilogue opened Pause, and Leave level left its caption stuck over the map) */if(cine)return;if($('#modal').open&&returning!==true){close();return;}if(hubPlacing()){hubCancelPlacing();toast('Put away. Place it again from Decorate at Home.',true);return;}const c=CLASSES[s.hero],where=world.zone==='town'&&!world.level?'Oakhaven':world.level?world.level.name:'';show('pause',`<div class="pause-wrap"><div class="pause-hero"><canvas id="pause-portrait" width="160" height="180" aria-hidden="true"></canvas><strong>${esc(s.heroNames?.[s.hero]||c.name)}</strong>${heroTitle(s)?`<small class="pause-title" data-title>${esc(heroTitle(s))}</small>`:''}<span class="pause-lv">Level ${s.level}</span>${where?`<small>${esc(where)}</small>`:''}<small class="pause-gold">◆ ${s.gold} gold</small></div><div class="pause-menu"><h2>Paused</h2><button id="resume" class="primary">Resume</button><div class="pause-more">${world.level?'<button id="pause-loadout">Choose abilities</button>':''}<button id="pause-help">Help</button><button id="pause-controls">Controls</button><button id="pause-settings">Settings</button>${/* v2:ui */pauseExtrasHTML(world.zone==='town'&&!world.level)}</div>${/* oct25-exploit: no Leave level once the boss has fallen (flow victory): leaving there banked the kill but dropped the clear, its gold, potion and clear XP */world.level&&world.flow!=='victory'?'<button id="abandon">Leave level</button>':''}<p class="subtle">Your progress is safe.</p></div></div>${pauseAbilitiesHTML({save:s,list:ABILITIES[s.hero]||[],loadout:activeLoadout(s),ready:a=>unlocked(s,a)&&!asleep(s,a),iconFor:a=>abilityIcon(a,s.hero),resource:c.resource,keys:abilityKeys(s).map(keyLabel),touch:document.documentElement.classList.contains('m-mode')})}`);portrait($('#pause-portrait'),c);$('#resume').focus({preventScroll:true});$('#resume').onclick=forceClose;$('#pause-settings').onclick=settings;$('#pause-controls').onclick=()=>controls(()=>pause(true));$('#pause-help').onclick=()=>help(()=>pause(true));wirePauseExtras({save:()=>s,welcome});/* v2:ui */$('#pause-loadout')?.addEventListener('click',loadout);$('#abandon')?.addEventListener('click',()=>{show('abandon',header('Leave this level?','Gold not yet saved from this level stays behind. Your learning and XP are safe.')+'<div class="modal-actions"><button id="stay">Keep adventuring</button><button id="leave">Leave level</button></div>');$('[data-close]').onclick=()=>pause(true);$('#stay').onclick=forceClose;$('#leave').onclick=()=>{forceClose();const lv=world.run?.levelUp;leaveLevel();announceLeft(lv);};});}
